// InterestProcessor.java — cursor-style vs set-based, plus a legit cursor case
package com.nbi.db;

import java.util.*;
import java.util.function.Consumer;

public class InterestProcessor {

    // CURSOR style: one row at a time (DECLARE/OPEN/FETCH/CLOSE loop).
    // Slower, holds state per row; shown for contrast, NOT recommended here.
    public int applyInterestCursor(List<Account> accounts, double rate) {
        int fetches = 0;
        Iterator<Account> cursor = accounts.iterator(); // OPEN
        while (cursor.hasNext()) {                       // WHILE rows remain
            Account row = cursor.next();                 // FETCH next row
            fetches++;
            row.balance = row.balance * (1 + rate);      // per-row processing
        }                                                // CLOSE at loop end
        return fetches; // number of per-row fetches (the overhead)
    }

    // SET-BASED style: one statement over the whole set (the right default).
    // UPDATE accounts SET balance = balance * (1 + :rate);
    public void applyInterestSetBased(List<Account> accounts, double rate) {
            accounts.replaceAll(a -> { a.balance = a.balance * (1 + rate);
            return a; });
        // conceptually a single bulk operation the engine optimizes
    }

    // LEGITIMATE cursor case: route each FLAGGED account to a per-type handler
    // that cannot be expressed as one set statement.
    public void routeFlaggedRowByRow(List<Account> accounts, Consumer<Account> reviewHandler) {
        for (Account row : accounts) {           // genuine row-by-row need
            if ("FLAGGED".equals(row.type)) {
                reviewHandler.accept(row);       // call different logic per row
            }
        }
    }
}
