// Demo.java — contrasts cursor vs set-based and shows a valid cursor use
package com.nbi.db;

import java.util.*;

public class Demo {
    public static void main(String[] args) {
        InterestProcessor p = new InterestProcessor();

        List<Account> viaCursor = new ArrayList<>(List.of(
            new Account("A1", 10000, "SAV"), new Account("A2", 20000, "SAV")));
        List<Account> viaSet = new ArrayList<>(List.of(
            new Account("A1", 10000, "SAV"), new Account("A2", 20000, "SAV")));

        int fetches = p.applyInterestCursor(viaCursor, 0.05); // row-by-row
        p.applyInterestSetBased(viaSet, 0.05);                // set-based

        System.out.println("CURSOR: per-row fetches = " + fetches
                + "  (overhead scales with row count)");
        System.out.printf("CURSOR result:    A1=%.0f A2=%.0f%n", viaCursor.get(0).balance, viaCursor.get(1).balance);
        System.out.printf("SET-BASED result: A1=%.0f A2=%.0f  (same result, one operation)%n",
                viaSet.get(0).balance, viaSet.get(1).balance);

        System.out.println("\nLegitimate cursor case (per-row routing of FLAGGED accounts):");
        List<Account> accts = List.of(
            new Account("A3", 500, "SAV"),
            new Account("A4", 99999, "FLAGGED"),
            new Account("A5", 100, "FLAGGED"));
        p.routeFlaggedRowByRow(accts, a ->
            System.out.println("  route " + a.id + " to manual review (balance " + a.balance + ")"));
    }
}
